tasks.solutionCode:
export async function getPaginatedProducts(page: number, pageSize: number = 20) {
  return await prisma.product.findMany({
    skip: (page - 1) * pageSize,
    take: pageSize,
    orderBy: { id: 'asc' }
  });
}

