tasks.solutionCode:
export async function getActivityStream(cursorId?: number, limit: number = 15) {
  return await prisma.activity.findMany({
    take: limit,
    ...(cursorId ? { skip: 1, cursor: { id: cursorId } } : {}),
    orderBy: { id: 'desc' }
  });
}

